def stop_positions(s,f):
    return [k for k in range(f, len(s)-2, 3) if s[k:k+3] in stops]

def run_end(s,f,x):
    # first stop position in frame f that aligns >= ... we want the end of stop-free run containing x
    # stop-free interval boundaries: greatest stop < x and least stop > x (codon starts)
    sp = stop_positions(s,f)
    nxt = [p for p in sp if p > x]
    prv = [p for p in sp if p + 3 <= x]
    end = nxt[0] if nxt else len(s)
    end = end + 3 if nxt else len(s)   # include stop codon end
    beg = (prv[-1]+3) if prv else 0
    return beg, end

