def hairpins(s, minstem=6, minloop=3, maxloop=20):
    res=[]
    L=len(s)
    for i in range(L):
        for j in range(i+minstem+minloop, min(L, i+minstem+maxloop+minstem+1)):
            # stem from i forward and j backward? define: 5' arm at i.., 3' arm ends at j
            k=0
            while i+k < j-k and s[i+k]==comp[s[j-k]] if (i+k< L and j-k>=0) else False:
                pass
            # simpler: compare s[i:i+k] with rc of s[j-k+1:j+1]
            k=0
            while True:
                a=i+k; b=j-k
                if a>=b: break
                if s[a]!=comp[s[b]]: break
                k+=1
            if k>=minstem:
                loop=j-k-(i+k)+1  # from i+k to j-k
                res.append((k, i, j, loop, s[i:i+k], s[j-k+1:j+1]))
    return res

