def slippery(c1,c2):
    return c1 in ('AAA','AAG','TTT','TTC') and c2 in ('AAA','AAG','TTT','TTC')

def best_shift(s, strand):
    L=len(s)
    out=[]
    for f in range(3):
        i=f
        while i < L-3:
            if s[i:i+3]=='ATG':
                # no-shift ORF
                e0 = nextstop(s,i)
                best=(e0-i)//3, None
                # walk codons, allow one shift
                p=i
                while p+3<=L-3:
                    c1=s[p:p+3]; c2=s[p+3:p+6]
                    if c1 in stops: break
                    if slippery(c1,c2):
                        for g,off in (((f-1)%3,-1),((f+1)%3,1)):
                            ns = p+off
                            e = nextstop(s,ns)
                            ln_shift = (p-i)//3 + (e-ns)//3
                            if ln_shift > best[0]:
                                best=(ln_shift, (p,c1,c2,off,e))
                    p+=3
                out.append((i, best))
                i = e0+3
            else:
                i+=3
    return out

